 50→/// Trait for user interface interactions.
 51→///
 52→/// This trait allows mocking the UI in tests.
 53→pub trait UserInterface {
 54→    /// Get the current output mode.
 55→    fn output_mode(&self) -> OutputMode;
 56→
 57→    /// Display a message to the user.
 58→    fn message(&mut self, msg: &str);
 59→
 60→    /// Display a success message.
 61→    fn success(&mut self, msg: &str);
 62→
 63→    /// Display a warning message.
 64→    fn warning(&mut self, msg: &str);
 65→
 66→    /// Display an error message.
 67→    fn error(&mut self, msg: &str);
 68→
 69→    /// Show a prompt and get user input.
 70→    fn prompt(&mut self, prompt: &Prompt) -> Result<PromptResult>;
 71→
 72→    /// Start a spinner for an operation.
 73→    fn start_spinner(&mut self, message: &str) -> Box<dyn SpinnerHandle>;
 74→
 75→    /// Start a spinner with leading indentation.
 76→    fn start_spinner_indented(&mut self, message: &str, indent: usize) -> Box<dyn SpinnerHandle> {
 77→        let _ = indent;
 78→        self.start_spinner(message)
 79→    }
 80→
 81→    /// Show a header/banner.
 82→    fn show_header(&mut self, title: &str);
 83→
 84→    /// Show progress (e.g., "Step 3 of 7").
 85→    fn show_progress(&mut self, current: usize, total: usize);
 86→
 87→    /// Check if running in interactive mode.
 88→    fn is_interactive(&self) -> bool;
 89→
 90→    /// Change the output mode at runtime.
 91→    fn set_output_mode(&mut self, mode: OutputMode);
 92→
 93→    /// Show a rich run header with app name, version, workflow, and step count.
 94→    fn show_run_header(
 95→        &mut self,
 96→        app_name: &str,
 97→        workflow: &str,
 98→        step_count: usize,
 99→        version: &str,
100→    ) {
101→        let _ = (workflow, step_count, version);
102→        self.show_header(app_name);
103→    }
104→
105→    /// Show/update workflow progress bar.
106→    fn show_workflow_progress(&mut self, current: usize, total: usize, elapsed: Duration) {
107→        let _ = elapsed;
108→        self.show_progress(current, total);
109→    }
110→
111→    /// Finish and remove the workflow progress bar.
112→    fn finish_workflow_progress(&mut self) {}
113→
114→    /// Show a contextual hint to the user.
115→    fn show_hint(&mut self, hint: &str) {
116→        self.message(hint);
117→    }
118→
119→    /// Show a bordered error block with command, output, and optional hint.
120→    fn show_error_block(&mut self, command: &str, output: &str, hint: Option<&str>) {
121→        self.error(command);
122→        if !output.is_empty() {
123→            self.message(output);
124→        }
125→        if let Some(h) = hint {
126→            self.show_hint(h);
127→        }
128→    }
129→
130→    /// Show a run summary with step results.
131→    fn show_run_summary(&mut self, summary: &RunSummary) {
132→        if summary.success {
133→            self.success(&format!(
134→                "Setup complete! ({} run, {} skipped)",
135→                summary.steps_run, summary.steps_skipped
136→            ));
137→        } else {
138→            self.error(&format!(
139→                "Setup failed at: {}",
140→                summary.failed_steps.join(", ")
141→            ));
142→        }
143→    }
144→}
145→
146→/// Summary of a workflow run, used by `show_run_summary`.
147→#[derive(Debug, Clone)]
148→pub struct RunSummary {
149→    /// Per-step results in execution order.
150→    pub step_results: Vec<StepSummary>,
151→    /// Total run duration.
152→    pub total_duration: Duration,
153→    /// Number of steps that ran.
154→    pub steps_run: usize,
155→    /// Number of steps skipped.
156→    pub steps_skipped: usize,
157→    /// Whether all steps succeeded.
158→    pub success: bool,
159→    /// Names of failed steps.
160→    pub failed_steps: Vec<String>,
161→}
162→
163→/// Summary of a single step's result.
164→#[derive(Debug, Clone)]
165→pub struct StepSummary {
166→    /// Step name.
167→    pub name: String,
168→    /// Step status.
169→    pub status: StatusKind,
170→    /// How long the step took.
171→    pub duration: Option<Duration>,
172→    /// Additional context (e.g., check description like "rustc --version").
173→    pub detail: Option<String>,
174→}
175→
176→/// Handle for controlling a spinner.
177→pub trait SpinnerHandle {
178→    /// Update the spinner message.
179→    fn set_message(&mut self, msg: &str);
180→
181→    /// Mark the operation as successful.
182→    fn finish_success(&mut self, msg: &str);
183→
184→    /// Mark the operation as failed.
185→    fn finish_error(&mut self, msg: &str);
186→
187→    /// Mark as skipped.
188→    fn finish_skipped(&mut self, msg: &str);
189→
190→    /// Get a clone of the underlying progress bar, if available.
191→    ///
192→    /// This is used for live output streaming: the cloned bar can be shared
193→    /// with an `OutputCallback` to update the spinner message in real-time.
194→    /// Returns `None` for mock/hidden spinners.
195→    fn progress_bar(&self) -> Option<ProgressBar> {
196→        None
197→    }
198→}
199→
200→/// A prompt to show to the user.
201→#[derive(Debug, Clone)]
202→pub struct Prompt {
203→    /// Unique key for the prompt (used for caching/lookup).
204→    pub key: String,
205→    /// The question to display.
206→    pub question: String,
207→    /// The type of prompt.
208→    pub prompt_type: PromptType,
209→    /// Default value if user just presses enter.
210→    pub default: Option<String>,
211→}
212→
213→/// The type of prompt.
214→#[derive(Debug, Clone)]
215→pub enum PromptType {
216→    /// Yes/no confirmation.
217→    Confirm,
218→    /// Free-form text input.
219→    Input,
220→    /// Select one from a list of options.
221→    Select { options: Vec<PromptOption> },
222→    /// Select multiple from a list of options.
223→    MultiSelect { options: Vec<PromptOption> },
224→}
225→
226→/// An option in a select prompt.
227→#[derive(Debug, Clone)]
228→pub struct PromptOption {
229→    /// Display label.
230→    pub label: String,
231→    /// Value returned when selected.
232→    pub value: String,
233→}
234→
235→/// Result of a prompt.
236→#[derive(Debug, Clone)]
237→pub enum PromptResult {
238→    /// Boolean result from confirm.
239→    Bool(bool),
240→    /// String result from input or select.
241→    String(String),
242→    /// Multiple string results from multi-select.
243→    Strings(Vec<String>),
244→}
245→
246→impl PromptResult {
247→    /// Get as string, suitable for interpolation.
248→    pub fn as_string(&self) -> String {
249→        match self {
250→            Self::Bool(b) => b.to_string(),
251→            Self::String(s) => s.clone(),
252→            Self::Strings(v) => v.join(","),
253→        }
254→    }
255→
256→    /// Get as bool if this is a Bool result.
257→    pub fn as_bool(&self) -> Option<bool> {
258→        match self {
259→            Self::Bool(b) => Some(*b),
260→            _ => None,
261→        }
262→    }
263→}
264→
265→#[cfg(test)]
266→mod tests {
267→    use super::*;
268→
269→    #[test]
270→    fn prompt_result_as_string_bool() {
271→        assert_eq!(PromptResult::Bool(true).as_string(), "true");
272→        assert_eq!(PromptResult::Bool(false).as_string(), "false");
273→    }
274→
275→    #[test]
276→    fn prompt_result_as_string_string() {
277→        assert_eq!(
278→            PromptResult::String("hello".to_string()).as_string(),
279→            "hello"
280→        );
281→    }
282→
283→    #[test]
284→    fn prompt_result_as_string_strings() {
285→        assert_eq!(
286→            PromptResult::Strings(vec!["a".to_string(), "b".to_string()]).as_string(),
287→            "a,b"
288→        );
289→    }
290→
291→    #[test]
292→    fn prompt_result_as_bool() {
293→        assert_eq!(PromptResult::Bool(true).as_bool(), Some(true));
294→        assert_eq!(PromptResult::String("test".to_string()).as_bool(), None);
295→    }
296→
297→    #[test]
298→    fn prompt_option_creation() {
299→        let opt = PromptOption {
300→            label: "Display Text".to_string(),
301→            value: "value".to_string(),
302→        };
303→        assert_eq!(opt.label, "Display Text");
304→        assert_eq!(opt.value, "value");
305→    }
306→
307→    #[test]
308→    fn prompt_type_variants() {
309→        let confirm = PromptType::Confirm;
310→        let input = PromptType::Input;
311→        let select = PromptType::Select { options: vec![] };
312→        let multi = PromptType::MultiSelect { options: vec![] };
313→
314→        // Just verify they can be created
315→        assert!(matches!(confirm, PromptType::Confirm));
316→        assert!(matches!(input, PromptType::Input));
317→        assert!(matches!(select, PromptType::Select { .. }));
318→        assert!(matches!(multi, PromptType::MultiSelect { .. }));
319→    }
320→
321→    #[test]
322→    fn multiselect_empty_selection_returns_empty_vec() {
323→        let result = PromptResult::Strings(vec![]);
324→        assert_eq!(result.as_string(), "");
325→    }
326→
327→    #[test]
328→    fn multiselect_single_selection() {
329→        let result = PromptResult::Strings(vec!["db".to_string()]);
330→        assert_eq!(result.as_string(), "db");
331→    }
332→
333→    #[test]
334→    fn multiselect_multiple_selections() {
335→        let result = PromptResult::Strings(vec![
336→            "db".to_string(),
337→            "cache".to_string(),
338→            "search".to_string(),
339→        ]);
340→        assert_eq!(result.as_string(), "db,cache,search");
341→    }
342→
343→    #[test]
344→    fn prompt_type_select_stores_options() {
345→        let options = vec![
346→            PromptOption {
347→                label: "Option A".to_string(),
348→                value: "a".to_string(),
349→            },
350→            PromptOption {
351→                label: "Option B".to_string(),
352→                value: "b".to_string(),
353→            },
354→        ];
355→
356→        let prompt_type = PromptType::Select {
357→            options: options.clone(),
358→        };
359→
360→        if let PromptType::Select { options: stored } = prompt_type {
361→            assert_eq!(stored.len(), 2);
362→            assert_eq!(stored[0].value, "a");
363→        } else {
364→            panic!("Expected Select variant");
365→        }
366→    }
367→
368→    #[test]
369→    fn prompt_type_multiselect_stores_options() {
370→        let options = vec![PromptOption {
371→            label: "Feature 1".to_string(),
372→            value: "f1".to_string(),
373→        }];
374→
375→        let prompt_type = PromptType::MultiSelect { options };
376→
377→        if let PromptType::MultiSelect { options: stored } = prompt_type {
378→            assert_eq!(stored.len(), 1);
379→        } else {
380→            panic!("Expected MultiSelect variant");
381→        }
382→    }
383→
384→    #[test]
385→    fn prompt_result_strings_preserves_order() {
386→        let result = PromptResult::Strings(vec![
387→            "first".to_string(),
388→            "second".to_string(),
389→            "third".to_string(),
390→        ]);
391→        assert_eq!(result.as_string(), "first,second,third");
392→    }
393→
