//! GitHub Actions output formatter.
//!
//! Emits [workflow commands](https://docs.github.com/en/actions/using-workflows/workflow-commands-for-github-actions)
//! (`::error::`, `::warning::`, `::notice::`) so that CI annotations appear
//! directly on the pull-request diff.

use std::collections::HashMap;
use std::time::Duration;

use crate::error::{BivvyError, Result};

use super::progress::format_duration;
use super::{
    OutputMode, Prompt, PromptResult, PromptType, RunSummary, SpinnerHandle, StatusKind,
    UserInterface,
};

/// Escape a string value for use inside a GitHub Actions workflow command property.
///
/// GitHub Actions uses `%25` for `%`, `%0A` for `\n`, `%0D` for `\r` inside
/// the properties portion of a command.
fn escape_property(s: &str) -> String {
    s.replace('%', "%25")
        .replace('\r', "%0D")
        .replace('\n', "%0A")
        .replace(':', "%3A")
        .replace(',', "%2C")
}

/// Escape message data in a GitHub Actions workflow command.
///
/// The message body uses `%25` for `%`, `%0A` for `\n`, `%0D` for `\r`.
fn escape_data(s: &str) -> String {
    s.replace('%', "%25")
        .replace('\r', "%0D")
        .replace('\n', "%0A")
}

/// UI implementation that emits GitHub Actions workflow commands.
///
/// Errors emit `::error::`, warnings emit `::warning::`, and
/// informational messages emit `::notice::`.  Spinners and progress bars
/// are replaced with `::group::` / `::endgroup::` blocks.
pub struct GitHubActionsUI {
    mode: OutputMode,
    env_overrides: HashMap<String, String>,
}

impl GitHubActionsUI {
    /// Create a new GitHub Actions UI.
    pub fn new() -> Self {
        let env_overrides: HashMap<String, String> = std::env::vars()
            .filter(|(k, _)| k.starts_with("BIVVY_PROMPT_"))
            .collect();

        Self {
            mode: OutputMode::GithubActions,
            env_overrides,
        }
    }

    /// Create with explicit overrides (for testing).
    #[cfg(test)]
    pub fn with_overrides(overrides: HashMap<String, String>) -> Self {
        Self {
            mode: OutputMode::GithubActions,
            env_overrides: overrides,
        }
    }
}

impl UserInterface for GitHubActionsUI {
    fn output_mode(&self) -> OutputMode {
        self.mode
    }

    fn message(&mut self, msg: &str) {
        println!("{}", msg);
    }

    fn success(&mut self, msg: &str) {
        println!("::notice::{}", escape_data(msg));
    }

    fn warning(&mut self, msg: &str) {
        println!("::warning::{}", escape_data(msg));
    }

    fn error(&mut self, msg: &str) {
        println!("::error::{}", escape_data(msg));
    }

    fn prompt(&mut self, prompt: &Prompt) -> Result<PromptResult> {
        let is_multiselect = matches!(prompt.prompt_type, PromptType::MultiSelect { .. });

        // Check environment override
        let env_key = format!("BIVVY_PROMPT_{}", prompt.key.to_uppercase());
        if let Some(value) = self.env_overrides.get(&env_key) {
            if is_multiselect {
                let values: Vec<String> = value.split(',').map(|s| s.trim().to_string()).collect();
                return Ok(PromptResult::Strings(values));
            }
            return Ok(PromptResult::String(value.clone()));
        }

        // Use default
        if let Some(default) = &prompt.default {
            if is_multiselect {
                let values: Vec<String> =
                    default.split(',').map(|s| s.trim().to_string()).collect();
                return Ok(PromptResult::Strings(values));
            }
            return Ok(PromptResult::String(default.clone()));
        }

        Err(BivvyError::ConfigValidationError {
            message: format!(
                "Cannot prompt for '{}' in non-interactive mode (no default value)",
                prompt.key
            ),
        })
    }

    fn start_spinner(&mut self, message: &str) -> Box<dyn SpinnerHandle> {
        println!("::group::{}", escape_data(message));
        Box::new(GitHubActionsSpinner)
    }

    fn start_spinner_indented(&mut self, message: &str, _indent: usize) -> Box<dyn SpinnerHandle> {
        self.start_spinner(message)
    }

    fn show_header(&mut self, title: &str) {
        println!("::notice::{}", escape_data(title));
    }

    fn show_progress(&mut self, current: usize, total: usize) {
        println!("[{}/{}]", current, total);
    }

    fn show_run_header(
        &mut self,
        app_name: &str,
        workflow: &str,
        step_count: usize,
        version: &str,
    ) {
        let step_label = if step_count == 1 { "step" } else { "steps" };
        println!(
            "::notice::bivvy {} v{} - {} workflow - {} {}",
            escape_data(app_name),
            version,
            workflow,
            step_count,
            step_label
        );
    }

    fn show_workflow_progress(&mut self, _current: usize, _total: usize, _elapsed: Duration) {
        // No-op: progress bars are noise in CI logs
    }

    fn finish_workflow_progress(&mut self) {}

    fn show_hint(&mut self, hint: &str) {
        println!("::notice::{}", escape_data(hint));
    }

    fn show_error_block(&mut self, command: &str, output: &str, hint: Option<&str>) {
        let mut msg = format!("Command failed: {}", command);
        if !output.is_empty() {
            msg.push_str(&format!(" | Output: {}", output));
        }
        if let Some(h) = hint {
            msg.push_str(&format!(" | Hint: {}", h));
        }
        println!("::error::{}", escape_data(&msg));
    }

    fn show_run_summary(&mut self, summary: &RunSummary) {
        for step in &summary.step_results {
            let detail = step
                .duration
                .map(format_duration)
                .or_else(|| step.detail.clone())
                .unwrap_or_default();

            match step.status {
                StatusKind::Failed => {
                    println!(
                        "::error::Step '{}' failed{}",
                        escape_property(&step.name),
                        if detail.is_empty() {
                            String::new()
                        } else {
                            format!(": {}", escape_data(&detail))
                        }
                    );
                }
                StatusKind::Warning => {
                    println!(
                        "::warning::Step '{}' warning{}",
                        escape_property(&step.name),
                        if detail.is_empty() {
                            String::new()
                        } else {
                            format!(": {}", escape_data(&detail))
                        }
                    );
                }
                _ => {
                    let icon = step.status.bracketed();
                    println!(
                        "{} {} {}",
                        icon,
                        step.name,
                        detail,
                    );
                }
            }
        }

        println!();
        if summary.success {
            println!(
                "::notice::Setup complete! Total: {} - {} run - {} skipped",
                format_duration(summary.total_duration),
                summary.steps_run,
                summary.steps_skipped,
            );
        } else {
            println!(
                "::error::Setup failed at: {}",
                escape_data(&summary.failed_steps.join(", "))
            );
        }
    }

    fn is_interactive(&self) -> bool {
        false
    }

    fn set_output_mode(&mut self, mode: OutputMode) {
        self.mode = mode;
    }
}

/// Spinner that emits ::endgroup:: on completion.
struct GitHubActionsSpinner;

impl SpinnerHandle for GitHubActionsSpinner {
    fn set_message(&mut self, _msg: &str) {}

    fn finish_success(&mut self, msg: &str) {
        println!("::notice::{}", escape_data(msg));
        println!("::endgroup::");
    }

    fn finish_error(&mut self, msg: &str) {
        println!("::error::{}", escape_data(msg));
        println!("::endgroup::");
    }

    fn finish_skipped(&mut self, msg: &str) {
        println!("::notice::{}", escape_data(msg));
        println!("::endgroup::");
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn escape_property_encodes_special_chars() {
        assert_eq!(escape_property("hello\nworld"), "hello%0Aworld");
        assert_eq!(escape_property("a:b,c"), "a%3Ab%2Cc");
        assert_eq!(escape_property("100%"), "100%25");
    }

    #[test]
    fn escape_data_encodes_newlines() {
        assert_eq!(escape_data("line1\nline2"), "line1%0Aline2");
        assert_eq!(escape_data("100%"), "100%25");
    }

    #[test]
    fn github_actions_ui_is_not_interactive() {
        let ui = GitHubActionsUI::new();
        assert!(!ui.is_interactive());
    }

    #[test]
    fn github_actions_ui_output_mode() {
        let ui = GitHubActionsUI::new();
        assert_eq!(ui.output_mode(), OutputMode::GithubActions);
    }

    #[test]
    fn prompt_uses_default() {
        let mut ui = GitHubActionsUI::new();
        let prompt = Prompt {
            key: "test".to_string(),
            question: "Test?".to_string(),
            prompt_type: PromptType::Input,
            default: Some("default_value".to_string()),
        };

        let result = ui.prompt(&prompt).unwrap();
        assert_eq!(result.as_string(), "default_value");
    }

    #[test]
    fn prompt_fails_without_default() {
        let mut ui = GitHubActionsUI::new();
        let prompt = Prompt {
            key: "test".to_string(),
            question: "Test?".to_string(),
            prompt_type: PromptType::Input,
            default: None,
        };

        assert!(ui.prompt(&prompt).is_err());
    }

    #[test]
    fn prompt_uses_env_override() {
        let mut overrides = HashMap::new();
        overrides.insert("BIVVY_PROMPT_DB".to_string(), "postgres".to_string());

        let mut ui = GitHubActionsUI::with_overrides(overrides);
        let prompt = Prompt {
            key: "db".to_string(),
            question: "Database?".to_string(),
            prompt_type: PromptType::Input,
            default: Some("sqlite".to_string()),
        };

        let result = ui.prompt(&prompt).unwrap();
        assert_eq!(result.as_string(), "postgres");
    }

    #[test]
    fn spinner_handle_methods_dont_panic() {
        let mut spinner = GitHubActionsSpinner;
        spinner.set_message("working...");
        spinner.finish_success("done");
    }
}

