//! GitHub Actions annotation formatter.
//!
//! Formats lint diagnostics as GitHub Actions workflow commands so they
//! appear as inline annotations on pull-request diffs.

use super::LintFormatter;
use crate::lint::{LintDiagnostic, Severity};
use std::io::Write;

/// Formats lint output as GitHub Actions workflow commands.
///
/// Each diagnostic becomes a `::error::`, `::warning::`, or `::notice::`
/// command. When source location is available, `file`, `line`, and `col`
/// properties are included so the annotation is pinned to the right line.
pub struct GitHubActionsFormatter;

impl GitHubActionsFormatter {
    /// Create a new GitHub Actions formatter.
    pub fn new() -> Self {
        Self
    }

    fn command_name(severity: Severity) -> &'static str {
        match severity {
            Severity::Error => "error",
            Severity::Warning => "warning",
            Severity::Hint => "notice",
        }
    }
}

impl LintFormatter for GitHubActionsFormatter {
    fn format<W: Write>(
        &self,
        diagnostics: &[LintDiagnostic],
        writer: &mut W,
    ) -> std::io::Result<()> {
        for diag in diagnostics {
            let cmd = Self::command_name(diag.severity);
            let title = format!("{}", diag.rule_id.0);

            if let Some(ref span) = diag.span {
                write!(
                    writer,
                    "::{} file={},line={},col={},title={}::{}",
                    cmd,
                    span.file.display(),
                    span.start_line,
                    span.start_col,
                    escape_property(&title),
                    escape_data(&diag.message),
                )?;
            } else {
                write!(
                    writer,
                    "::{} title={}::{}",
                    cmd,
                    escape_property(&title),
                    escape_data(&diag.message),
                )?;
            }

            if let Some(ref suggestion) = diag.suggestion {
                write!(writer, "%0AHint: {}", escape_data(suggestion))?;
            }

            writeln!(writer)?;
        }

        Ok(())
    }
}

/// Escape a property value for GitHub Actions workflow commands.
fn escape_property(s: &str) -> String {
    s.replace('%', "%25")
        .replace('\r', "%0D")
        .replace('\n', "%0A")
        .replace(':', "%3A")
        .replace(',', "%2C")
}

/// Escape message data for GitHub Actions workflow commands.
fn escape_data(s: &str) -> String {
    s.replace('%', "%25")
        .replace('\r', "%0D")
        .replace('\n', "%0A")
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::lint::{RuleId, Span};

    #[test]
    fn formats_error_with_location() {
        let formatter = GitHubActionsFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("circular-dependency"),
            Severity::Error,
            "Circular dependency detected: a -> b -> a",
        )
        .with_span(Span::line("config.yml", 10))];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.starts_with("::error "));
        assert!(output.contains("file=config.yml"));
        assert!(output.contains("line=10"));
        assert!(output.contains("title=circular-dependency"));
        assert!(output.contains("::Circular dependency detected"));
    }

    #[test]
    fn formats_warning_without_location() {
        let formatter = GitHubActionsFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("app-name"),
            Severity::Warning,
            "App name contains spaces",
        )];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.starts_with("::warning "));
        assert!(output.contains("title=app-name"));
        assert!(output.contains("::App name contains spaces"));
        assert!(!output.contains("file="));
    }

    #[test]
    fn formats_hint_as_notice() {
        let formatter = GitHubActionsFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("suggestion"),
            Severity::Hint,
            "Consider adding a description",
        )];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.starts_with("::notice "));
    }

    #[test]
    fn includes_suggestion() {
        let formatter = GitHubActionsFormatter::new();
        let diagnostics =
            vec![
                LintDiagnostic::new(RuleId::new("test"), Severity::Warning, "Issue found")
                    .with_suggestion("Try renaming"),
            ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains("Hint: Try renaming"));
    }

    #[test]
    fn empty_diagnostics_produces_empty_output() {
        let formatter = GitHubActionsFormatter::new();
        let mut output = Vec::new();
        formatter.format(&[], &mut output).unwrap();
        assert!(output.is_empty());
    }

    #[test]
    fn multiple_diagnostics_each_on_own_line() {
        let formatter = GitHubActionsFormatter::new();
        let diagnostics = vec![
            LintDiagnostic::new(RuleId::new("r1"), Severity::Error, "Error one"),
            LintDiagnostic::new(RuleId::new("r2"), Severity::Warning, "Warning two"),
        ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();
        let lines: Vec<&str> = output.lines().collect();

        assert_eq!(lines.len(), 2);
        assert!(lines[0].starts_with("::error "));
        assert!(lines[1].starts_with("::warning "));
    }
}

